-- Read-through completion is part of the same write as the final lesson.
CREATE TRIGGER IF NOT EXISTS learning_readthrough_completion
AFTER INSERT ON learning_lesson_progress
BEGIN
  INSERT INTO learning_completions (account_id,course_id,revision,completed_at)
  SELECT e.account_id,e.course_id,e.revision,NEW.completed_at
  FROM learning_enrolments e JOIN learning_course_versions v ON v.course_id=e.course_id AND v.revision=e.revision
  WHERE e.id=NEW.enrolment_id AND v.state IN ('published','retired') AND v.practical=''
    AND json_array_length(v.lessons_json)>0
    AND (SELECT COUNT(*) FROM learning_lesson_progress p
      WHERE p.enrolment_id=e.id AND p.lesson_number BETWEEN 1 AND json_array_length(v.lessons_json))=json_array_length(v.lessons_json)
  ON CONFLICT (account_id,course_id,revision) DO NOTHING;
END;

-- Update original starter courses only while they are untouched drafts.
UPDATE learning_course_versions SET lessons_json=json_set(lessons_json,
  '$[0].questions',json('[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An outgoing officer gives you a folder and a list headed finished. What do you check first?","choices":[{"id":"a","text":"Which decisions and open actions the authoritative records actually support."},{"id":"b","text":"Whether the folder contains the latest contact list to copy into your notes."},{"id":"c","text":"Whether the count of actions matches the last agenda only."}],"correct_choice_id":"a","explanation":"A usable handover is based on the actual records and current status.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A confidential member document relates to an open task. What goes in the handover?","choices":[{"id":"a","text":"A full copy attached to the general office handover."},{"id":"b","text":"An authorised reference and who can access the private record."},{"id":"c","text":"A summary with the member''s private details pasted into the task list."}],"correct_choice_id":"b","explanation":"The next officer needs the record location and permission, not a new copy.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]'),
  '$[1].questions',json('[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A draft motion changes during the meeting. What should the rehearsal minutes include?","choices":[{"id":"a","text":"The original agenda wording and only the number of votes."},{"id":"b","text":"The final wording, outcome, owner and any due date."},{"id":"c","text":"The chair''s summary of the discussion with no motion exact enough to trace."}],"correct_choice_id":"b","explanation":"The record should state what the meeting decided and who takes it forward.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A fictional receipt does not match the agreed amount. What should a rehearsal report flag?","choices":[{"id":"a","text":"A corrected number that makes the report balance without stating the reason."},{"id":"b","text":"A matched payment based on the fact that a receipt exists."},{"id":"c","text":"The discrepancy, sources and person responsible for checking it."}],"correct_choice_id":"c","explanation":"The discrepancy needs its own follow-up and supporting evidence.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]'),
  '$[2].questions',json('[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The outgoing officer offers their login so the incoming officer can get started. What should happen?","choices":[{"id":"a","text":"Share the login just until the new officer checks the equipment."},{"id":"b","text":"Keep the same credentials and record the new office holder separately."},{"id":"c","text":"Have the approved administrator grant the new officer''s own role access."}],"correct_choice_id":"c","explanation":"An individual account keeps access and responsibility attached to the right person.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An equipment item is missing from the changeover. What goes in the record?","choices":[{"id":"a","text":"The item, last known custody, who will follow up and the next check."},{"id":"b","text":"A receipt for the items present with the missing item marked as returned."},{"id":"c","text":"The estimated cost without an owner or custody history."}],"correct_choice_id":"a","explanation":"A clear exception gives the incoming officer a way to resolve it.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]'),
  '$[3].questions',json('[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The incoming officer cannot find an approval for a task due tomorrow. What are the next steps?","choices":[{"id":"a","text":"Flag the gap, ask the authorised person to verify it and set a check-in."},{"id":"b","text":"Assume the deadline means the task was authorised."},{"id":"c","text":"Leave it on the handover list until the following month''s meeting."}],"correct_choice_id":"a","explanation":"An imminent task still needs its authority confirmed.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"How do you close the first-week handover review?","choices":[{"id":"a","text":"Confirm only that both officers attended the review."},{"id":"b","text":"Record resolved items, remaining owners and when outstanding issues will be checked."},{"id":"c","text":"Copy the original tasks to a new list without checking their status."}],"correct_choice_id":"b","explanation":"The handover needs an up-to-date record of responsibility and follow-up.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]')), edit_version=edit_version+1
WHERE course_id='plfc-officer-handover' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL
  AND json_extract(lessons_json,'$[0].title')='Prepare before the changeover'
  AND json_extract(lessons_json,'$[1].title')='Run a first meeting rehearsal'
  AND json_extract(lessons_json,'$[2].title')='Hand over access and equipment'
  AND json_extract(lessons_json,'$[3].title')='Check the first week';

UPDATE learning_course_versions SET practical='',edit_version=edit_version+1
WHERE course_id='plfc-volunteer-onboarding' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

