INSERT INTO learning_course_versions (course_id,revision,state,title,description,lessons_json,practical) VALUES
  ('plfc-site-tour',1,'draft','Find your way around the PLFC clubhouse',
   'A quick tour for anyone curious about the fishing club, its website or their first local meet.',
   json_array(
     json('{"title":"Start with the public clubhouse","body":"Find the fishing guide, conditions, club calendar and public events. Open the demo and choose Guide me if you want help getting around. Confirm the details of an event with the organiser before travelling.","captureNotes":"Record the demo homepage, calendar and fishing guide using public or fictional examples. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
     json('{"title":"Find the right door","body":"Use the join information to compare membership options. Members use their own sign-in for the areas they are allowed to see. If you are unsure which area to use, ask the club through its published contact route."}')
   ),
   ''),
  ('plfc-president',1,'draft','PLFC President handover',
   'Prepare a meeting, chair a decision and carry the result into the next club update.',
   json_array(
     json('{"title":"Prepare with the Secretary","body":"Open the next agenda together. Identify items for information, discussion and decision. Check what the rules and committee require for attendance, conflicts of interest and the wording of motions.","captureNotes":"Use the demo Meeting desk and a fictional motion. Show where agenda papers and draft minutes are found. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The agenda contains a proposal and a report for information. What should you clarify before the meeting?","choices":[{"id":"a","text":"Which item the Secretary will read first and how long it gets."},{"id":"b","text":"Which item needs a decision, what authority applies and which papers support it."},{"id":"c","text":"Whether both items could be combined into one motion for speed."}],"correct_choice_id":"b","explanation":"Checking authority and what each item needs helps the chair use the right process.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A person declares an interest in an item during the meeting. What is your first procedural step?","choices":[{"id":"a","text":"Let everyone finish the discussion and decide afterwards if it mattered."},{"id":"b","text":"Ask the person to describe the interest with the intention of treating all disclosures the same."},{"id":"c","text":"Check the club rules for handling the interest and have the disclosure recorded."}],"correct_choice_id":"c","explanation":"The meeting should follow the rule that applies to this interest and keep its record.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Close the loop","body":"Ask the Secretary to read back the wording of the decision. Give each action an owner and due date. Review the newsletter preview and check that the President’s message reflects what the club has agreed to share.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The committee agreed to explore a new venue. What should the President send to the newsletter?","choices":[{"id":"a","text":"That the club is exploring the venue and what was agreed about the next step."},{"id":"b","text":"That the club selected a new venue subject to routine confirmation."},{"id":"c","text":"A draft announcing a booking, with the decision described separately in the minutes."}],"correct_choice_id":"a","explanation":"The public update should match the decision actually made.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A motion changed during discussion. What belongs in the minutes?","choices":[{"id":"a","text":"The final wording and actual outcome"},{"id":"b","text":"The first draft wording copied from the agenda"}],"correct_choice_id":"a","explanation":"The record needs to reflect the decision actually made.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]}')
   ),
   'Prepare a chair’s handover for a fictional meeting. Include the agenda item that needs a decision, a way to handle a disclosed interest, the action owner and the public message still awaiting review.'),
  ('plfc-vice-president',1,'draft','PLFC Vice President handover',
   'Back up the chair and keep the next local meet moving.',
   json_array(
     json('{"title":"Agree where you are covering","body":"Check the agenda with the President and agree which items you will chair or follow up. Record what you have authority to decide and which matters you should bring back.","captureNotes":"Show the demo agenda and public event calendar together. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The President asks you to cover two items and is away when an unrelated decision comes up. What do you do?","choices":[{"id":"a","text":"Treat cover for the meeting as delegation for every item."},{"id":"b","text":"Delay the two assigned items until the President can review them in person."},{"id":"c","text":"Check your delegated scope and refer the unrelated decision through the authorised route."}],"correct_choice_id":"c","explanation":"The scope of cover determines what you can lead or decide.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"The next agenda lists a task as complete but its owner says it needs approval. What do you pass on?","choices":[{"id":"a","text":"The task is waiting on a named approval, with the current owner and next check."},{"id":"b","text":"The task is complete because the agenda is the official record."},{"id":"c","text":"Move it to the next local meet checklist without recording the disagreement."}],"correct_choice_id":"a","explanation":"Recording the actual status lets the President resolve the gap.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Check the next local meet","body":"Confirm the date, meeting point, welcome lead and equipment lead. Check with the responsible officer before promising a date to another club. Send a short update to the newsletter and check its contribution status.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two clubs are interested in a meet but equipment is still unconfirmed. Which update is ready?","choices":[{"id":"a","text":"Announce the date with equipment as an internal note."},{"id":"b","text":"State the proposed date, who is checking equipment and when confirmation is due."},{"id":"c","text":"Wait for the newsletter to go out before assigning an equipment owner."}],"correct_choice_id":"b","explanation":"The update must describe the plan at its actual level of commitment.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What should go in your handover about the next meet?","choices":[{"id":"a","text":"The draft event title by itself"},{"id":"b","text":"Confirmed arrangements and named owners for outstanding work"}],"correct_choice_id":"b","explanation":"The next officer needs to know what is settled and who can resolve the gaps.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]}')
   ),
   'Write a one-page handover for a fictional meet with one unconfirmed date, one equipment job and a newsletter update in review.'),
  ('plfc-secretary',1,'draft','PLFC Secretary handover',
   'Find the live meeting and newsletter work, record decisions and hand over the club’s calendar.',
   json_array(
     json('{"title":"Prepare and file the committee record","body":"Check the next meeting date, agenda and carried actions. Record the actual wording and result of motions. Keep the committee record and working notes in the private desk and use the approved release process for member minutes.","captureNotes":"Show the demo meeting desk and a fictional member edition. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A meeting approves a motion with an amendment. How do you prepare the member minutes?","choices":[{"id":"a","text":"Record the approved wording and outcome, then use the committee''s member-release process."},{"id":"b","text":"Publish the agenda wording and attach the amendment in the private notes."},{"id":"c","text":"Include the full working discussion so readers can reconstruct the result."}],"correct_choice_id":"a","explanation":"The member copy needs the agreed result and the approved audience.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"The agenda lists a carried action but two people think the other owns it. What goes into your draft?","choices":[{"id":"a","text":"Both people listed as independently responsible without checking."},{"id":"b","text":"A note to confirm the owner against the decision record and agree who follows up."},{"id":"c","text":"A new owner selected because they sent the last email."}],"correct_choice_id":"b","explanation":"An action needs an accountable owner tied to the actual record.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Coordinate member correspondence","body":"Check the current newsletter edition and who is publishing it. Confirm any returning membership offer with the club register and the Treasurer’s waiver decision where relevant. Pass the private invitation to its intended recipient.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The membership record exists but a proposed waiver is still pending. What do you hand over?","choices":[{"id":"a","text":"A ready-to-send invitation with the waiver assumed."},{"id":"b","text":"A general newsletter reminder for every returning member."},{"id":"c","text":"The verified record, pending waiver and the person to check with before issuing a link."}],"correct_choice_id":"c","explanation":"The invitation and the decision on a waiver are separate steps.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Who should receive a returning member’s private link?","choices":[{"id":"a","text":"The intended member after the relevant checks"},{"id":"b","text":"Everyone on the newsletter list"}],"correct_choice_id":"a","explanation":"The private link is for the named recipient.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]}')
   ),
   'Draft a handover note with the next meeting, an unfinished action, the status of a fictional newsletter edition and a pending member correspondence item.'),
  ('plfc-assistant-secretary',1,'draft','PLFC Assistant Secretary handover',
   'Share the meeting follow-up and newsletter workload with the Secretary.',
   json_array(
     json('{"title":"Share a desk without duplicating work","body":"Agree who follows up each open meeting action and who will assemble, review and publish the next newsletter. Check the current version before editing. Use the contribution history to see what is still due.","captureNotes":"Capture the demo newsletter and officer task history with synthetic names. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two officers both start editing the same newsletter. What is the best way to proceed?","choices":[{"id":"a","text":"Each finish an edition and ask the President to choose after both are ready."},{"id":"b","text":"Agree who owns the next edit, which version is current and who will release it."},{"id":"c","text":"Use the version with the most new content, regardless of who has release duties."}],"correct_choice_id":"b","explanation":"A shared version and clear release ownership prevent duplicate work.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A meeting task appears done in a message but its register entry is open. What should you confirm first?","choices":[{"id":"a","text":"Whether the message is recent enough to copy into the register."},{"id":"b","text":"Whether a newer task can replace the old open entry."},{"id":"c","text":"Whether the task owner confirms completion and what evidence belongs in the record."}],"correct_choice_id":"c","explanation":"The task owner and source help the team confirm the actual status.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Bring paper and replies back into the record","body":"File returned task sheets under the matching officer and clarify unclear ticks or updates with the person who wrote them. Agree who will respond to any membership reply or prepare a member notice.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A returned sheet has a tick beside two similar jobs. What should you do?","choices":[{"id":"a","text":"Ask the officer which job the mark refers to before updating that record."},{"id":"b","text":"Close the job with the earlier due date."},{"id":"c","text":"Close both and note that the paper sheet is ambiguous."}],"correct_choice_id":"a","explanation":"The club record needs an unambiguous update.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two officers are working on the same newsletter. What do you agree first?","choices":[{"id":"a","text":"That each officer should publish an edition"},{"id":"b","text":"Who will own each edit, review and release step"}],"correct_choice_id":"b","explanation":"Clear ownership prevents duplicate notices and conflicting versions.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]}')
   ),
   'Prepare a fictional weekly handover listing the draft newsletter, replies still due, three owners and the next check-in with the Secretary.'),
  ('plfc-treasurer',1,'draft','PLFC Treasurer handover',
   'Review membership payments, stock and the next report with the incoming Treasurer.',
   json_array(
     json('{"title":"Reconcile the payment trail","body":"Match each fictional membership payment or shop receipt to the corresponding register entry. Identify missing evidence. Record approved waivers separately from money received and confirm which reports are ready for committee review.","captureNotes":"Use demo entries in the Stock and reports desks. Leave real balances and invoices out of the recording. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"One register receipt has no corresponding deposit. How do you present it for review?","choices":[{"id":"a","text":"Post the deposit from the expected amount and correct it next month if needed."},{"id":"b","text":"Move the receipt to waiver records because payment cannot be located."},{"id":"c","text":"Record the mismatch and follow up before treating it as reconciled."}],"correct_choice_id":"c","explanation":"Showing a mismatch preserves the evidence and the question to resolve.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A waiver and a cash payment are the same amount. What should the report show?","choices":[{"id":"a","text":"The waiver and received funds in their respective records."},{"id":"b","text":"One combined amount under received membership revenue."},{"id":"c","text":"Only the cash payment, with no record of the waiver."}],"correct_choice_id":"a","explanation":"Committee review needs to see the different transaction types.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Pass on stock and reporting","body":"Show how delivery costs, missing invoices and counts are tracked. Compare the last stocktake with a physical count. Provide a report date and list the items awaiting evidence or committee approval. Use individual accounts and agreed access when transferring responsibilities.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A delivery is counted but the supplier invoice has not arrived. What do you hand over?","choices":[{"id":"a","text":"A delivered quantity with last year''s cost marked confirmed."},{"id":"b","text":"The count, missing cost evidence and who is following it up."},{"id":"c","text":"A zero stock value with instructions to remove the delivery until invoiced."}],"correct_choice_id":"b","explanation":"The incoming Treasurer needs the actual status of stock and missing cost evidence.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"How should an approved fee waiver appear?","choices":[{"id":"a","text":"As a waiver separate from cash received"},{"id":"b","text":"As income that has arrived in the bank"}],"correct_choice_id":"a","explanation":"A waiver and a receipt are different records.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]}')
   ),
   'Use made-up amounts to reconcile two receipts and one approved waiver. Flag a missing stock invoice and draft the questions for the next Treasurer.'),
  ('plfc-webmaster',1,'draft','PLFC Webmaster handover',
   'Hand over clubhouse access and support using the demo or a sanctioned test account.',
   json_array(
     json('{"title":"Match access to a club decision","body":"Confirm the approved role and who authorised it. Use a named account and the intended invitation. Have the recipient check the areas their role needs and escalate an access problem through the club support route.","captureNotes":"Record the public demo and a supervised test view. Keep real activation links, credentials and member records out. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A new officer has been named but their account is still pending. What do you check?","choices":[{"id":"a","text":"The authorised role decision, individual account and intended invitation recipient."},{"id":"b","text":"The job title in the public announcement as sufficient authority."},{"id":"c","text":"Whether the departing officer''s account can be left in use for the handover week."}],"correct_choice_id":"a","explanation":"The person''s own account needs a confirmed access decision.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An incoming officer can open their test view but needs another desk. What''s your first step?","choices":[{"id":"a","text":"Give broad temporary access and revisit the need after handover."},{"id":"b","text":"Check the approved role and whether that desk is within its scope."},{"id":"c","text":"Ask them to test with someone else''s access before requesting a change."}],"correct_choice_id":"b","explanation":"Testing should stay within the account and role authorised.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Give the next webmaster a support list","body":"Document the owner of the club account, current support requests, outstanding access changes and recovery contacts through the club’s approved records. Review access when an officer changes role.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An outgoing officer still has access to an old desk. What goes into the handover?","choices":[{"id":"a","text":"The outgoing officer''s login and a reminder to reset it later."},{"id":"b","text":"A note that the issue is solved when the new officer signs in."},{"id":"c","text":"The affected account and desk, the decision owner and the pending access review."}],"correct_choice_id":"c","explanation":"The authorised access change needs an owner and a check of its outcome.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What do you pass to the incoming webmaster?","choices":[{"id":"a","text":"Everyone’s saved passwords"},{"id":"b","text":"An authorised access checklist and support history"}],"correct_choice_id":"b","explanation":"The incoming administrator needs their own account and a clear source of authority.","source_refs":["https://plfc-clubhouse.auraofintelligence.workers.dev/"]}]}')
   ),
   'Write a fictional support handover covering one incoming officer, one outgoing officer and a member who needs a private follow-up.'),
  ('plfc-adult-member',1,'draft','PLFC Adult member welcome',
   'Get around the member clubhouse and plan your first meet or fishing activity.',
   json_array(
     json('{"title":"Open your member area","body":"Find the member calendar, approved member updates and your own account details. Ask the club about activation and paid membership if an expected area is unavailable.","captureNotes":"Show the public clubhouse and an authorised adult demo account. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
     json('{"title":"Plan a first outing","body":"Check the event details and ask what to bring and who will meet you. Keep private catch locations, personal details and pictures within the audience you mean to share them with."}')
   ),
   ''),
  ('plfc-cadet-member',1,'draft','PLFC Cadet member and guardian welcome',
   'Help a cadet and their guardian plan a supported first club session.',
   json_array(
     json('{"title":"Plan the first visit together","body":"Choose a suitable club activity with the guardian. Ask who will lead, how the young person checks in and which equipment they should bring. The guardian deals with the application and current permissions.","captureNotes":"Use a fictional family and the public membership information. Keep details of real young people private. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
     json('{"title":"Ask before sharing","body":"Check with the designated lead about supervision and photo arrangements. Ask the guardian separately about online participation and check the club’s review before using those features."}')
   ),
   ''),
  ('plfc-junior-member',1,'draft','PLFC Junior member and guardian welcome',
   'Find an appropriate junior activity and understand the clubhouse sharing choices.',
   json_array(
     json('{"title":"Choose an activity with your guardian","body":"Ask about the activity, skill level, supervision and equipment before coming along. Confirm the meeting point and what to do if you or the guardian need help.","captureNotes":"Show the public youth application choice and fictional event details. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
     json('{"title":"Use the online area with approved access","body":"Speak up if you are unsure about an online message, photo or activity. A guardian and the club review online participation separately. Ask the lead how to report a concern."}')
   ),
   ''),
  ('plfc-social-member',1,'draft','PLFC Social member welcome',
   'Find club gatherings, member notices and ways to help out socially.',
   json_array(
     json('{"title":"Find a gathering","body":"Use public events and member updates to find a gathering. Confirm what is open to your category with the club contact.","captureNotes":"Show a fictional social meet in the public demo calendar. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
     json('{"title":"Put your hand up for a task","body":"If you offer to help with a meal or fundraiser, confirm the shift with the organiser. Ask which announcements or photos can be shared."}')
   ),
   ''),
  ('plfc-casual-member',1,'draft','PLFC Casual member welcome',
   'Check the conditions for a visit or one-off activity before making plans.',
   json_array(
     json('{"title":"Confirm what the category covers","body":"Find the club’s current public join information. Ask which activity your casual membership covers and whether there are fees, capacity limits or advance arrangements.","captureNotes":"Capture the public join options with no application entered. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
     json('{"title":"Check in for the day","body":"Bring the public event details and confirm your meeting point and contact. Ask how to find updates if the plans change and report anything the next crew should know."}')
   ),
   ''),
  ('plfc-lifetime-member',1,'draft','PLFC Lifetime member welcome',
   'Find the current clubhouse, check your existing record and choose how to contribute.',
   json_array(
     json('{"title":"Update your connection with the club","body":"Use the club contact to confirm the current lifetime membership record and sign-in. Ask how to update your preferences and where to find member notices.","captureNotes":"Show the demo sign-in and a fictional member contact update. Reference site: https://plfc-clubhouse.auraofintelligence.workers.dev/"}'),
     json('{"title":"Share knowledge by agreement","body":"Offer a story, guide or mentoring time to the club. Check before sharing another member’s names, records, old photos or private catch locations."}')
   ),
   '')
ON CONFLICT (course_id,revision) DO NOTHING;

