INSERT INTO learning_course_versions (course_id,revision,state,title,description,lessons_json,practical) VALUES
  ('sandy-site-tour',1,'draft','Explore the Sandy Sports proposal',
   'Find the proposed sport, film, places and training pages and choose what to help shape.',
   json_array(
     json('{"title":"Tour the proposed programme","body":"Start with the programme and places pages. Compare sports, outdoor film and possible facilities. Mark which items are proposals, examples or open for a conversation.","captureNotes":"Capture the public programme and places pages. Use visual labels for proposed and confirmed information. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
     json('{"title":"Choose a way to help","body":"Use the interest page to offer a sport, skill, venue conversation or help with formation. Ask what is being planned and who needs to agree before promising a date or place."}')
   ),
   ''),
  ('sandy-president',1,'draft','Sandy Sports President preparation',
   'Rehearse chairing a formation meeting and create a first handover for a proposed President.',
   json_array(
     json('{"title":"Prepare decisions for the founding group","body":"Draft an agenda about purpose, activities and first priorities. Write which decisions are within the founding group’s authority and who else needs to agree, especially about use of places and public commitments.","captureNotes":"Use the demo governance desk to rehearse an inaugural agenda. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two agenda items depend on different authorities. What preparation helps the meeting?","choices":[{"id":"a","text":"Combine them as one founding vote covering all approvals."},{"id":"b","text":"List the decision sought and who can actually make it for each item."},{"id":"c","text":"Leave the authority question until someone objects on the day."}],"correct_choice_id":"b","explanation":"The group needs to know which decisions are in its power.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A motion to explore a venue replaces a motion to hire it. What wording goes in the record?","choices":[{"id":"a","text":"The hire proposal brought to the meeting, plus the chair''s intended outcome."},{"id":"b","text":"A headline about the venue and an instruction to check the notes later."},{"id":"c","text":"The final scope to explore, with the named follow-up."}],"correct_choice_id":"c","explanation":"The approved wording and follow-up show the real scope.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Chair and hand over","body":"Practise checking interests, asking for input, reading back outcomes and assigning actions. Leave the successor a dated list of open decisions, proposed expenses and people to contact.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The next chair finds two old minutes and a current request. What should your handover highlight?","choices":[{"id":"a","text":"The definite decisions, open matters and the next source or authority to check."},{"id":"b","text":"The newest minutes as sufficient proof for the request."},{"id":"c","text":"The latest private conversation as the basis for announcing a decision."}],"correct_choice_id":"a","explanation":"The incoming chair needs traceable decisions and an accurate status.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A possible venue is mentioned in the meeting. What can you publish?","choices":[{"id":"a","text":"Its current proposal status and any approved wording"},{"id":"b","text":"That approval has already been given"}],"correct_choice_id":"a","explanation":"Meeting discussion and venue approval have separate evidence.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
   ),
   'Draft an inaugural meeting agenda, one example decision, a note on venue authority and three actions for a successor.'),
  ('sandy-vice-president',1,'draft','Sandy Sports Vice President preparation',
   'Set up a backup for the chair and coordinate work across proposed activities.',
   json_array(
     json('{"title":"Agree a practical backup plan","body":"Discuss with the proposed chair when you would lead and which decisions need group confirmation. Set a way for sport, film and facilities leads to raise a clash or missing resource.","captureNotes":"Record a fictional handover in the demo committee workspace. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The chair asks you to cover risk and equipment discussions. A membership vote comes up. What do you do?","choices":[{"id":"a","text":"Chair the vote because you are already covering the meeting."},{"id":"b","text":"Cancel the scheduled equipment discussion until all roles are filled."},{"id":"c","text":"Confirm whether membership decisions are in the cover agreement."}],"correct_choice_id":"c","explanation":"Cover has a defined scope, and the status matters for decisions.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Sport and film leads have discussed using the same gear. What should you record?","choices":[{"id":"a","text":"Each proposed use, when it is needed and who can agree the allocation."},{"id":"b","text":"The first request only, because it arrived first."},{"id":"c","text":"A final allocation based on which workstream has a longer written plan."}],"correct_choice_id":"a","explanation":"A clear comparison gives the responsible group what it needs to decide.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Make an activity walkthrough","body":"Select one proposed activity. Check the event lead, potential site, readiness, costs and decision still needed. Report the next action and who can do it.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"One trial has a lead and budget but no permission. How do you pass it on?","choices":[{"id":"a","text":"Mark it ready because the lead and budget are available."},{"id":"b","text":"Document what is ready and the named permission check still open."},{"id":"c","text":"Move the plan to the published calendar pending permission."}],"correct_choice_id":"b","explanation":"Status includes the dependencies required for the actual trial.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A sport and a film proposal need the same place. What comes first?","choices":[{"id":"a","text":"Announce both dates as if they are booked"},{"id":"b","text":"Confirm the constraints and take a clear choice to the responsible group"}],"correct_choice_id":"b","explanation":"The group needs a concrete decision with the constraints visible.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
   ),
   'Write a fictional cover plan for a meeting and one venue clash, with a suggested action owner and decision date.'),
  ('sandy-secretary',1,'draft','Sandy Sports Secretary preparation',
   'Start a formation record, organise drafts and leave clear actions for the next meeting.',
   json_array(
     json('{"title":"Build the first record","body":"Bring the draft rules, meeting notice, agenda and current proposals together. Label drafts and keep author, date and version. Record the actual decision and current status of each matter.","captureNotes":"Open the constitution and governance demo with a fictional rules edit. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A revised rule arrives shortly before a meeting. How do you prepare it?","choices":[{"id":"a","text":"Label its version and place it with the decision needed and relevant prior text."},{"id":"b","text":"Replace the old draft so the group only sees the revision."},{"id":"c","text":"Circulate it as current rules to reduce confusion on the day."}],"correct_choice_id":"a","explanation":"Version history and decision status show what the group would actually be considering.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A discussion ends without agreement. What should the minutes show?","choices":[{"id":"a","text":"A decision inferred from the majority of comments."},{"id":"b","text":"The deferred item, information needed and who will bring it back."},{"id":"c","text":"The discussion title only, with nothing for the next agenda."}],"correct_choice_id":"b","explanation":"The next Secretary needs the actual status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Keep the follow-up clear","body":"List the owner, deadline and reference for each action. Prepare accurate wording for people who asked about joining or helping. Keep expressions of interest and private contact details in the appropriate records.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An interested person asks whether sending an enquiry gives them a vote. What is your response?","choices":[{"id":"a","text":"Use the proposed constitution as if its terms have been adopted."},{"id":"b","text":"Give the person a conditional vote based on the reply date."},{"id":"c","text":"Explain the current status and where future approved voting terms would be recorded."}],"correct_choice_id":"c","explanation":"Interest, proposals and adopted or authorised terms must stay distinct.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What belongs with an agreed action?","choices":[{"id":"a","text":"Owner, date and a link or reference to the decision"},{"id":"b","text":"A task with no owner or source"}],"correct_choice_id":"a","explanation":"The next Secretary needs to verify what was agreed.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
   ),
   'Prepare fictional meeting notes with a draft rule, one agreed action and one deferred decision. Add a handover for the next date.'),
  ('sandy-assistant-secretary',1,'draft','Sandy Sports Assistant Secretary preparation',
   'Back up the formation record and organise follow-up where this role is adopted.',
   json_array(
     json('{"title":"Divide the shared workload","body":"Agree who prepares the agenda, collects reports, checks updates and sends a reviewed reply. Record what you can do independently and when the proposed Secretary needs to confirm.","captureNotes":"Use a fictional shared task list in the demo committee room. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"You and the Secretary have different agenda drafts. What is the first step?","choices":[{"id":"a","text":"Merge the files yourself and circulate the result as final."},{"id":"b","text":"Agree which version is current and who is responsible for the next edit."},{"id":"c","text":"Keep your own version and let the chair reconcile them in the meeting."}],"correct_choice_id":"b","explanation":"Agree one version and clear ownership before publishing or meeting.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Several volunteers have replied to a draft invitation. What should your handover capture?","choices":[{"id":"a","text":"The entire reply thread pasted into the public demo for continuity."},{"id":"b","text":"Only the number of replies, with no ownership or record reference."},{"id":"c","text":"Which replies need action, who will handle them and where the private source belongs."}],"correct_choice_id":"c","explanation":"The next officer needs useful status and private handling of real details.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Prepare a clean handover","body":"Reconcile the paper notes and draft files before the next meeting. Send the Secretary a short list of incomplete replies and records awaiting review. Keep personal details out of the browser demo.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Paper notes and the shared list disagree on a due date. What should you do?","choices":[{"id":"a","text":"Check the source decision or ask the task owner, then update the correct record."},{"id":"b","text":"Always use the date typed into the shared list."},{"id":"c","text":"Keep both dates without saying which is intended."}],"correct_choice_id":"a","explanation":"The record should reflect an agreed due date and its source.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Where should real contact details be entered while using a public demo?","choices":[{"id":"a","text":"In the public browser demo so they are easy to find"},{"id":"b","text":"Only in an appropriate private process authorised by the project"}],"correct_choice_id":"b","explanation":"The demo is for fictional planning and rehearsals.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
   ),
   'Make a fictional shared checklist for a meeting and a volunteer invitation. Set an owner and handover point for each.'),
  ('sandy-treasurer',1,'draft','Sandy Sports Treasurer preparation',
   'Build a starting budget and a handover for grant, donation and equipment discussions.',
   json_array(
     json('{"title":"Price one proposal","body":"Create a simple activity budget with quantities, evidence, income assumptions and dates. Label contributions and grants by their actual status. Include the costs of delivery and looking after equipment.","captureNotes":"Show the public funding model with a fictional set of amounts. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"You are estimating a film trial with an offered screen but unknown delivery costs. What should you budget?","choices":[{"id":"a","text":"Count the screen''s advertised value as a cash contribution and leave delivery blank."},{"id":"b","text":"Exclude all equipment costs because the main item was offered."},{"id":"c","text":"Track the screen offer by status and include delivery and operating costs to check."}],"correct_choice_id":"c","explanation":"A workable budget explains the offer and every material cost assumption.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A proposal shows three income sources with different certainty. What helps a reviewer?","choices":[{"id":"a","text":"Show confirmed and proposed sources separately, with evidence or a follow-up owner."},{"id":"b","text":"Add them into one total and discuss the uncertainty at the meeting."},{"id":"c","text":"Show only the confirmed income and remove any record of the funding gap."}],"correct_choice_id":"a","explanation":"Decision-makers need to see the gap and which contributions might close it.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Track approvals and receipts","body":"Record who could approve a purchase, the actual applicant or operator, where receipts go and when the budget will be reviewed. Keep real payments in the authorised system and figures in the demo fictional.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An invoice arrives with a higher total than approval. What''s your next step?","choices":[{"id":"a","text":"Record it as approved because a supplier invoice was received."},{"id":"b","text":"Check the agreed approval and ask the authorised person to review the difference."},{"id":"c","text":"Reallocate another line to cover it without recording a change."}],"correct_choice_id":"b","explanation":"An invoice records a claim and the approved amount still needs to be checked.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"How should a grant application awaiting a result appear?","choices":[{"id":"a","text":"As a possible income source with its status"},{"id":"b","text":"As money already available"}],"correct_choice_id":"a","explanation":"The Treasurer needs to distinguish a proposal from available funds.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
   ),
   'Make a fictional budget for a come-and-try session or screening and identify one estimate to confirm, one approval and the review date.'),
  ('sandy-webmaster',1,'draft','Sandy Sports Webmaster preparation',
   'Walk through planned website access, draft publication and the first officer handover.',
   json_array(
     json('{"title":"Rehearse the different views","body":"Use the demo to check what a visitor, a prospective member and a local officer would need to find. Document which access is proposed and which feature is ready to test.","captureNotes":"Record the public or view-only demo. Avoid real credentials or invitations. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A visitor can see a demo summary and expects to see real member records. How do you respond?","choices":[{"id":"a","text":"Explain the demo view and use a fictional record to demonstrate the relevant action."},{"id":"b","text":"Temporarily expose a real member page so the visitor can understand it."},{"id":"c","text":"Send a screenshot of the live member record after blurring only its name."}],"correct_choice_id":"a","explanation":"A demonstration can use fictional information without exposing private records.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An office role changes. What do you check after the authorised access update?","choices":[{"id":"a","text":"Only whether an admin can still reach the settings page."},{"id":"b","text":"The incoming and outgoing individual accounts against the approved scopes."},{"id":"c","text":"The incoming person''s access, then leave the old access until the next meeting."}],"correct_choice_id":"b","explanation":"Both identities need a verification of the approved access result.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Log changes and support","body":"Record each requested permission, its authorisation and the affected pages. Rehearse how to reply to a support request using made-up details. Ask the accountable person to confirm any publication.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A request asks you to publish the date of a proposed event. What do you record?","choices":[{"id":"a","text":"The requested date as confirmed because it was submitted to the website desk."},{"id":"b","text":"A general announcement without recording how it was approved."},{"id":"c","text":"Who requested it, what approvals apply and which wording is still a draft."}],"correct_choice_id":"c","explanation":"Publishing status and authority need a traceable record.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What do you need before giving a person office-holder access?","choices":[{"id":"a","text":"A request from a social comment"},{"id":"b","text":"An authorised decision and the right account"}],"correct_choice_id":"b","explanation":"An individual access change needs an identified person, role and authority.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
   ),
   'Draft a fictional access handover with one member view issue, one proposed officer invitation and one page change waiting for approval.'),
  ('sandy-sport-lead',1,'draft','Sandy Sports Sport lead preparation',
   'Design a proposed come-and-try session that a new lead could take over.',
   json_array(
     json('{"title":"Plan one session","body":"Pick one activity, such as beach volleyball or flag football. Draft who it is for, the space and gear it needs, the lead and backups, and how a beginner would join in.","captureNotes":"Show the proposed sport programme and one fictional run sheet. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A beginner session includes a game and equipment demo. What should the plan include?","choices":[{"id":"a","text":"The full game first, with beginner rules figured out at check-in."},{"id":"b","text":"Who leads each activity, equipment needed and how a beginner can join safely."},{"id":"c","text":"The name of the gear and contact only, with roles chosen at the venue."}],"correct_choice_id":"b","explanation":"A beginner needs a workable plan and someone responsible for support.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A proposed site has enough space but unclear access. What belongs in your plan?","choices":[{"id":"a","text":"The site named as available because the dimensions suit."},{"id":"b","text":"A backup date at the same site without checking access."},{"id":"c","text":"The person who can confirm access and the decision date before announcing."}],"correct_choice_id":"c","explanation":"Space suitability alone does not grant use of it.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Prepare to confirm the session","body":"Check who can agree to the site, equipment, supervision and event conditions. Record the point at which the lead would change or stop the plan. Carry decisions and unresolved matters into a handover.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Just before your proposed trial, conditions change. What does the handover need?","choices":[{"id":"a","text":"Who can pause or change the session, which channel to use and the agreed trigger."},{"id":"b","text":"The name of the next rostered helper as final decision-maker."},{"id":"c","text":"The original weather plan only and a general note to watch conditions."}],"correct_choice_id":"a","explanation":"A useful contingency has a decision owner, trigger and communication route.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What should the next Sport lead know before sharing the event date?","choices":[{"id":"a","text":"Which arrangements are confirmed and which checks are open"},{"id":"b","text":"The date by itself"}],"correct_choice_id":"a","explanation":"Someone needs to own the checks that make the plan workable.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
   ),
   'Write a fictional 45-minute session plan with beginner instructions, a lead and backup, one site approval and a change-of-plan point.'),
  ('sandy-film-lead',1,'draft','Sandy Sports Film Club lead preparation',
   'Plan an outdoor cinema or film club trial with clear approvals and crew roles.',
   json_array(
     json('{"title":"Choose the format and people","body":"Set out the proposed screening or workshop, willing audience and responsibilities. Agree who would confirm venue access, screening permission or media releases before advertising.","captureNotes":"Use the Film Club and events desks with a fictional film and date. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A venue contact expresses interest and the team picks a film. What stays open?","choices":[{"id":"a","text":"Only the projection check because the venue showed interest."},{"id":"b","text":"Only the final event graphic and social posting time."},{"id":"c","text":"Venue agreement, screening permission and responsibilities before announcement."}],"correct_choice_id":"c","explanation":"Interest and a film idea are inputs to the checks, not proof of approval.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"One person wants both projection and audience welcome at the same time. What do you do?","choices":[{"id":"a","text":"Separate the tasks or agree backup coverage in the run sheet."},{"id":"b","text":"Leave both with the same person and rely on the event start time."},{"id":"c","text":"Remove the welcome step without checking audience needs."}],"correct_choice_id":"a","explanation":"The schedule needs owners who can do each job at the required time.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Hand over the screening plan","body":"Draft the timeline for setup, sound and projection checks, audience welcome, pause or cancellation and pack-down. Tell the next lead which equipment and approvals still need confirmation.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A caption test fails during rehearsal. How do you hand it over?","choices":[{"id":"a","text":"Treat it as fixed when a new file is downloaded."},{"id":"b","text":"Record the fault, who checks the replacement and the point for a go or pause decision."},{"id":"c","text":"Ask the projectionist to decide on the day without updating the run sheet."}],"correct_choice_id":"b","explanation":"A test result and a responsible next check make the plan usable.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What belongs in a draft screening handover?","choices":[{"id":"a","text":"A public date without a permissions check"},{"id":"b","text":"The status of permissions as well as crew and equipment"}],"correct_choice_id":"b","explanation":"The next lead needs to know what has been agreed.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
   ),
   'Plan a fictional film night with a crew lead, venue contact, permissions checks, a weather call and a pack-down owner.'),
  ('sandy-facilities-lead',1,'draft','Sandy Sports Facilities lead preparation',
   'Compare possible places and hand over equipment, access and maintenance questions.',
   json_array(
     json('{"title":"Prepare a site visit","body":"Use the places and facilities pages to separate an idea from an agreed site. For a walk-through, note proposed access, amenities, storage, weather exposure and who can confirm arrangements.","captureNotes":"Capture the public space planner using a fictional layout. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A planning drawing includes a nearby storage spot. What should a site visit establish?","choices":[{"id":"a","text":"Who permits storage, practical access and the conditions for safe use."},{"id":"b","text":"Whether the drawing can be made more detailed before asking the site owner."},{"id":"c","text":"Whether gear has fitted there at unrelated events."}],"correct_choice_id":"a","explanation":"A potential spot still needs permission and fit for the current purpose.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two locations have similar capacity but different accessible routes. How do you compare them?","choices":[{"id":"a","text":"Select the area with the most capacity on the drawing."},{"id":"b","text":"Record the actual routes, barriers, unresolved checks and responsible contacts."},{"id":"c","text":"Give both the same accessibility rating based on distance from the centre."}],"correct_choice_id":"b","explanation":"Evidence and named checks support a useful comparison.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Record the equipment and site dependencies","body":"List who would procure, store, check and maintain equipment. Write down costs, constraints and unanswered questions before presenting options. Pass the evidence and open actions to the next lead.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An offered trailer solves storage but needs ongoing care. What should you record?","choices":[{"id":"a","text":"The estimated price only so it can be added to the asset list."},{"id":"b","text":"The offered trailer as owned by the club until someone objects."},{"id":"c","text":"Ownership, return or maintenance terms and the person responsible."}],"correct_choice_id":"c","explanation":"The offer, actual ownership and ongoing responsibilities must stay clear.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A useful space appears on a map. What is the next step?","choices":[{"id":"a","text":"Check the owner or operator and document the conditions for use"},{"id":"b","text":"Treat the map marker as access permission"}],"correct_choice_id":"a","explanation":"Maps support a site conversation and approval comes through the responsible party.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
   ),
   'Compare two fictional places for a sports and film event. Record one accessibility check, storage choice and site conversation for each.'),
  ('sandy-resident-member',1,'draft','Sandy Sports Island resident welcome',
   'Explore the proposed local adult membership option and say what should be available locally.',
   json_array(
     json('{"title":"Find the local activities","body":"Compare planned activities in Dunwich, Amity Point and Point Lookout. Ask what is being proposed, who is organising it and how to hear about a confirmed trial.","captureNotes":"Show the public programme and activity information. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
     json('{"title":"Shape what membership could mean","body":"Use the interest route to share one activity and one contribution you could make. Ask about proposed responsibilities and how the founding group will decide fees or participation."}')
   ),
   ''),
  ('sandy-non-resident-member',1,'draft','Sandy Sports Non-resident welcome',
   'Explore participation from off-island and check event access before making plans.',
   json_array(
     json('{"title":"Find a suitable activity","body":"Look for proposed sessions and the event contact. Ask about availability, timings and who would be able to take part. Check your own travel plans separately.","captureNotes":"Capture the public places and programme pages. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
     json('{"title":"Offer a realistic commitment","body":"Share how often you could take part and what support or skills you can offer. Ask which membership and activity arrangements are being considered for people who live off-island."}')
   ),
   ''),
  ('sandy-junior-member',1,'draft','Sandy Sports Junior and guardian welcome',
   'Help a young person and guardian ask the right questions about proposed sessions.',
   json_array(
     json('{"title":"Choose a session together","body":"Look for the proposed age group, activity and experience level. Ask the responsible contact how supervision, check-in and pickup would be organised before agreeing to take part.","captureNotes":"Use fictional family details and only public proposed session pages. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
     json('{"title":"Check safeguarding and sharing","body":"Ask who handles safety and how to raise a concern. Discuss photo, video and online sharing separately so the guardian and young person understand the choice."}')
   ),
   ''),
  ('sandy-supporter',1,'draft','Sandy Sports Supporter welcome',
   'Offer skills, time, equipment or another contribution to the proposed club.',
   json_array(
     json('{"title":"Choose a practical offer","body":"Find one activity, facility or project you could support. Identify the item, time or skill and what conditions come with it. Discuss the right next step with the project contact.","captureNotes":"Show the public interest and equipment wishes pages. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
     json('{"title":"Agree how it may be recognised","body":"Ask who would receive or hold a resource, how it would be returned and what may be said publicly. Record what is offered separately from what has been accepted."}')
   ),
   ''),
  ('sandy-film-participant',1,'draft','Sandy Sports Film Club participant welcome',
   'Choose whether to watch, help at a screening or learn behind the scenes.',
   json_array(
     json('{"title":"Choose how you want to take part","body":"Explore the film club and proposed screenings. Ask whether a session is for an audience, a workshop crew or people learning a particular task.","captureNotes":"Show a public film club concept and fictional workshop listing. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
     json('{"title":"Prepare for your first session","body":"Confirm the venue, timing, lead and what to bring. If you want to record or appear in footage, ask about notices, permissions and sharing before capturing or posting."}')
   ),
   ''),
  ('sandy-volunteer',1,'draft','Sandy Sports Volunteer welcome',
   'Practise checking in, working with a lead and handing over a proposed event shift.',
   json_array(
     json('{"title":"Ask about a real task","body":"Read the proposed role and say when you are available. Before treating a shift as agreed, confirm the lead, duties, meeting point, backup and equipment.","captureNotes":"Capture a fictional run sheet from an agreed demo or paper example. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
     json('{"title":"Work within the briefing","body":"Ask who manages a weather or safety change. Check before taking over supervision, using gear or taking photos. Report concerns and hand back the equipment and unfinished actions."}')
   ),
   ''),
  ('sandy-committee-member',1,'draft','Sandy Sports Committee member preparation',
   'Prepare for a possible committee role and take a first task through the draft, review and handover steps.',
   json_array(
     json('{"title":"Find the work you can help with","body":"Look at the proposed committee desks for governance, events, membership, funding and publishing. Agree a task with a lead, the decision it depends on and what needs a second person to review.","captureNotes":"Use the demo committee home and one fictional event task. Leave real account invitations and person records off-screen. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A proposed task has no owner and a pending venue check. What do you record?","choices":[{"id":"a","text":"A published date as a way of inviting a volunteer to own it."},{"id":"b","text":"An owner to confirm, the open dependency and the next decision point."},{"id":"c","text":"The venue shown in the proposal as the responsible task owner."}],"correct_choice_id":"b","explanation":"A workable task needs both a person and an honest dependency status.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"You have a connection to a supplier under discussion. What is your first step?","choices":[{"id":"a","text":"Wait until the proposal is published and then attach a note."},{"id":"b","text":"Ask another committee member to vote for your preferred option without raising it."},{"id":"c","text":"Raise the relevant interest through the agreed committee process."}],"correct_choice_id":"c","explanation":"The committee needs the disclosure before using the relevant decision process.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Work on a draft decision","body":"Record evidence, status, owner and due date. Raise relevant interests through the agreed process and pass a proposal to the people who can decide it. Tell the next officer which step still needs attention.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A draft says approved but no decision record is attached. How should it be handed over?","choices":[{"id":"a","text":"Flag the gap and ask the responsible person to confirm before relying on it."},{"id":"b","text":"Treat the label as enough and add the evidence after publishing."},{"id":"c","text":"Remove the draft and start a replacement so no decision is needed."}],"correct_choice_id":"a","explanation":"A status needs evidence and an accountable source.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"When can a draft event date be shared as confirmed?","choices":[{"id":"a","text":"When it appears in a committee planning desk"},{"id":"b","text":"After the person with authority has agreed the date and wording"}],"correct_choice_id":"b","explanation":"Status and authority tell the next officer whether a plan can be acted on.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
   ),
   'Take a fictional task from the committee desk. Write the next action, owner, one authority check, the status for any public message and the handover point.'),
  ('sandy-founding-member',1,'draft','Sandy Sports Founding participant welcome',
   'Follow the club''s formation, find your prospective member area and offer a practical contribution.',
   json_array(
     json('{"title":"Find your starting point","body":"Open Join and My Membership. Use the current instructions for expressing interest or using any joining option the operator has made available. The preview lets you see how the area works using fictional information.","captureNotes":"Show the public Join page and labelled My Membership preview. Use fictional names and no sign-up details. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
     json('{"title":"Bring one founding idea","body":"Offer a skill, time or idea for sport, film or facilities. Ask how input on the club purpose, proposed rules and first activities is collected. Confirm what the operator has actually agreed before representing the club to others."}')
   ),
   '')
ON CONFLICT (course_id,revision) DO NOTHING;

-- Straddie Noticeboard Network
INSERT INTO learning_courses (id,category_id,site_id,provider_name) VALUES
  ('noticeboard-site-tour','site-tours','noticeboard-training','Straddie Noticeboard Network'),
  ('noticeboard-community-contributor','member-start','noticeboard-training','Straddie Noticeboard Network'),
  ('noticeboard-business-publisher','member-start','noticeboard-training','Straddie Noticeboard Network'),
  ('noticeboard-editorial-review','noticeboard','noticeboard-training','Straddie Noticeboard Network'),
  ('noticeboard-feed-steward','noticeboard','noticeboard-training','Straddie Noticeboard Network'),
  ('noticeboard-venue-host','noticeboard','noticeboard-training','Straddie Noticeboard Network'),
  ('noticeboard-screen-caretaker','noticeboard','noticeboard-training','Straddie Noticeboard Network'),
  ('noticeboard-welcome-volunteer','volunteers','noticeboard-training','Straddie Noticeboard Network')
ON CONFLICT (id) DO NOTHING;

INSERT INTO learning_course_versions (course_id,revision,state,title,description,lessons_json,practical) VALUES
  ('noticeboard-site-tour',1,'draft','Explore the Straddie Noticeboard Network',
   'Learn where to find local notices, use the practice board and see who issues important updates.',
   json_array(
     json('{"title":"Find a public notice","body":"Open the homepage, then visit the board and try a filter. Read the named publisher, place, source and expiry before relying on the information. Look at the training page for the practice workflow.","captureNotes":"Capture the public board and training page using a fictional notice. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
     json('{"title":"Follow a changed plan","body":"Compare a notice with its public source. If a transport or official warning matters to your plans, check the issuing agency directly. Send a correction or question to the responsible contact."}')
   ),
   ''),
  ('noticeboard-community-contributor',1,'draft','Noticeboard community contributor welcome',
   'Draft a useful notice and share it with the right person for review.',
   json_array(
     json('{"title":"Prepare a draft","body":"Open the draft editor. Write a clear headline, place, start time, expiry and the public source. Include only the contact information and images agreed for publication.","captureNotes":"Show the browser draft editor and a fictional arts-night notice. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
     json('{"title":"Choose the outlets","body":"Select where you would like the notice to appear: web, venue TV or touch kiosk. Preview each requested outlet and give the approved reviewer a review copy with those choices."}')
   ),
   ''),
  ('noticeboard-business-publisher',1,'draft','Noticeboard local business publisher welcome',
   'Prepare clear business information and nominate who can approve corrections.',
   json_array(
     json('{"title":"Choose information people can act on","body":"Check a public business listing or service-hours notice. State the business name, location, hours, source and end date for a temporary change. Confirm who can speak for the business.","captureNotes":"Use the public business directory and a made-up closure or opening-hours change. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A cafe will close early this Thursday only. What should the notice say?","choices":[{"id":"a","text":"The regular business hours with the temporary change in an unlabelled note."},{"id":"b","text":"The new hours as an indefinite listing until the business changes them again."},{"id":"c","text":"The affected location and date, revised hours, source and expiry."}],"correct_choice_id":"c","explanation":"A time-limited change should be specific enough for visitors to act on.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two staff members send conflicting hours. What should happen before review?","choices":[{"id":"a","text":"Ask the nominated business contact to confirm the current hours and source."},{"id":"b","text":"Use whichever set of hours matches last month''s listing."},{"id":"c","text":"Publish a range of both hours and wait for people to report an issue."}],"correct_choice_id":"a","explanation":"The business contact can resolve which information is authoritative.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Review permission before offering it","body":"Get approval for the selected outlet, contact details and images. Give the reviewer a way to check the details and tell them which person will confirm changes or request removal.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The business approves text for web and TV but asks to exclude its image from TV. What do you send?","choices":[{"id":"a","text":"A single combined version that the venue can shorten if needed."},{"id":"b","text":"Outlet-specific versions and the image restriction in the reviewer copy."},{"id":"c","text":"The version with no image restrictions because the wording is the same."}],"correct_choice_id":"b","explanation":"Approval can vary by both channel and asset.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"When a temporary notice ends, what should the reviewer have?","choices":[{"id":"a","text":"An instruction to keep showing it until someone complains"},{"id":"b","text":"A clear expiry and a contact who can confirm the next update"}],"correct_choice_id":"b","explanation":"A clear expiry prevents out-of-date information from carrying on.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}')
   ),
   'Prepare a fictional business hours notice and a follow-up correction. Identify the approving contact, expiry and selected outlets.'),
  ('noticeboard-editorial-review',1,'draft','Noticeboard reviewer desk',
   'Check the source, scope and approval of a notice before authorising display.',
   json_array(
     json('{"title":"Review against the original","body":"Match the draft with the named public source. Check the place, timing, publisher approval and permissions for people and images. Compare the content against the intended outlet and return unclear items to the issuer.","captureNotes":"Capture a fictional draft and reviewed example from the public publishing guide. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The event flyer and draft disagree about the start time. How do you review it?","choices":[{"id":"a","text":"Ask the issuer to confirm its current source and resolve the mismatch first."},{"id":"b","text":"Use the draft''s time because it reached review later than the flyer."},{"id":"c","text":"Use the flyer time and leave the mismatch out of the decision record."}],"correct_choice_id":"a","explanation":"A reviewer should resolve the discrepancy with the responsible issuer.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A public photo is linked but its reuse permissions are unclear. Which action fits?","choices":[{"id":"a","text":"Approve the photo on a venue screen only because it will be seen briefly."},{"id":"b","text":"Ask for a cleared image or send the wording for review without the image."},{"id":"c","text":"Approve the image if the issuer can promise someone will check later."}],"correct_choice_id":"b","explanation":"The media permission must be clear for the planned use.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Check each update","body":"Agree the revised wording and effective time. Record who reviewed it and when, the intended outlets and the expiry. Tell the steward and venue contact how to check a correction or withdrawal.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A revised notice should take effect in ten minutes. What goes in the review record?","choices":[{"id":"a","text":"The replacement text and no timing because a future check will catch changes."},{"id":"b","text":"Only the new time, with the old version left up until its expiry."},{"id":"c","text":"Agreed wording, effective time, outlets, expiry, reviewer and how hosts check it."}],"correct_choice_id":"c","explanation":"A correction needs clear coordination and verification for the affected outlets.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"The copy asks for kiosk display but the issuer approved only web. What do you do?","choices":[{"id":"a","text":"Ask for confirmation or keep the approval to web"},{"id":"b","text":"Add it to the kiosk because the format fits"}],"correct_choice_id":"a","explanation":"Approval covers the agreed outlets.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}')
   ),
   'Review a fictional notice with a source mismatch and a missing expiry. Write the questions to send back and the details you would record once cleared.'),
  ('noticeboard-feed-steward',1,'draft','Noticeboard feed steward handover',
   'Maintain approved records and hand over corrections, expiry and take-downs.',
   json_array(
     json('{"title":"Prepare the approved record","body":"From the reviewed copy, confirm the stable notice ID, source, responsible publisher, time checked, expiry and agreed outlets. Use the practice guide to rehearse a change under the same ID.","captureNotes":"Show the public practice board with a staged feed example. Keep write access and credentials private. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An approved draft has an ID but no public source. What do you do?","choices":[{"id":"a","text":"Use the practice board URL as a substitute source."},{"id":"b","text":"Return it for a verifiable source before preparing the approved feed record."},{"id":"c","text":"Use a private review link as the public source so there is a link."}],"correct_choice_id":"b","explanation":"The public source should allow the responsible notice information to be checked.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A notice is withdrawn and one host is offline. What belongs in the handover?","choices":[{"id":"a","text":"A note that withdrawn means every screen is already clear."},{"id":"b","text":"A copy of the last approved notice so the venue can restore it."},{"id":"c","text":"The withdrawal, affected outlets, verification gap and who will check the offline display."}],"correct_choice_id":"c","explanation":"The feed decision and the visible screen state need separate verification.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Promote and verify a correction","body":"Follow the current authorised publishing process. Have the relevant host confirm what is actually showing. Record a take-down or withdrawal and escalate when the feed or display cannot be checked.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An updated feed has the right date but an old venue remains on a screen. What''s the next check?","choices":[{"id":"a","text":"Check the affected display and state with its host against the current record."},{"id":"b","text":"Retire the corrected notice and create a new record without checking the device."},{"id":"c","text":"Assume the screen shows an unrelated notice and close the issue."}],"correct_choice_id":"a","explanation":"The host can help check the actual outlet and whether it has the current record.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"The time changes for the same event. How should the steward identify it?","choices":[{"id":"a","text":"Create a duplicate notice and leave the first one live"},{"id":"b","text":"Keep the notice ID and record a fresh review and correction"}],"correct_choice_id":"b","explanation":"A stable identity helps remove the outdated version from the same locations.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}')
   ),
   'Write a fictional correction and take-down plan covering the old and new times, review, outlets, host checks and what to do if the feed is unavailable.'),
  ('noticeboard-venue-host',1,'draft','Noticeboard venue host welcome',
   'Prepare to host a public screen and agree who maintains it.',
   json_array(
     json('{"title":"Agree what the screen is for","body":"Identify the host contact, audience, allowed outlets, local notices and opening hours. Work through power, connectivity, physical access and equipment responsibility before confirming a trial.","captureNotes":"Capture the public hosting or pilot page and a fictional venue setup. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
     json('{"title":"Check what visitors actually see","body":"Practise opening the display, identifying when it was checked and reporting an issue. Agree how staff handle a stale notice, an unavailable feed and an official warning."}')
   ),
   ''),
  ('noticeboard-screen-caretaker',1,'draft','Noticeboard screen caretaker handover',
   'Check screen uptime and record which device, notice and connection need follow-up.',
   json_array(
     json('{"title":"Check display, connection and source","body":"Use the practice display to identify the device, outlet, last check and feed state. Compare it with a current source and report what appears on the actual screen.","captureNotes":"Record the public practice screen and one fictional offline rehearsal. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A screen is powered but it shows an old notice. What do you investigate first?","choices":[{"id":"a","text":"The display, last successful check and whether the feed contains the current record."},{"id":"b","text":"Replace the screen immediately because old content always indicates a device fault."},{"id":"c","text":"Change the notice wording independently in the feed."}],"correct_choice_id":"a","explanation":"Checking the actual display and source helps locate the fault.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two screens report issues after a connection change. What does the log need?","choices":[{"id":"a","text":"One common fault name so both can be marked fixed together."},{"id":"b","text":"Distinct device and venue details, time, symptoms, checks and escalation owner."},{"id":"c","text":"Only the venue Wi-Fi name and a screenshot from the better screen."}],"correct_choice_id":"b","explanation":"Separate device records give owners something to verify.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Log the fault and return to service","body":"Record the time, observed status and who owns the response. Follow the agreed local checklist. Verify the display and notify the venue or steward when the checked service is restored.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The screen has reconnected. What completes a return-to-service check?","choices":[{"id":"a","text":"See that the screen turns on and close the report."},{"id":"b","text":"Wait until someone reports a fresh problem before checking content."},{"id":"c","text":"Verify a current notice and visible display state, then tell the responsible contacts."}],"correct_choice_id":"c","explanation":"A powered and connected device still needs its displayed content checked.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A connection is down. What should you pass on first?","choices":[{"id":"a","text":"A claim that the feeder service has recovered"},{"id":"b","text":"What the display shows, when checked and the responsible contact"}],"correct_choice_id":"b","explanation":"The recorded observation lets the responsible person decide what to do.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}')
   ),
   'Write a fictional outage log with three checkpoints and a clear return-to-service check.'),
  ('noticeboard-welcome-volunteer',1,'draft','Noticeboard visitor welcome volunteer',
   'Point visitors to sources and practise a safe handover when plans change.',
   json_array(
     json('{"title":"Check in and find the current briefing","body":"Confirm the lead, location and duty. Compare the welcome briefing with the current source before directing a visitor. Know how to contact the venue and the notice steward.","captureNotes":"Use the public visitor and volunteer rehearsal. Leave real guest information off-screen. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
     json('{"title":"Hand over a change","body":"Report the old and new instructions, source, time checked and unresolved question to the lead. Ask them to confirm the wording visitors should use while a screen is offline."}')
   ),
   '')
ON CONFLICT (course_id,revision) DO NOTHING;

-- Minjerribah Screen & Media Network
INSERT INTO learning_courses (id,category_id,site_id,provider_name) VALUES
  ('msmn-site-tour','site-tours','msmn-training','Minjerribah Screen & Media Network'),
  ('msmn-story-contributor','member-start','msmn-training','Minjerribah Screen & Media Network'),
  ('msmn-trainee','member-start','msmn-training','Minjerribah Screen & Media Network'),
  ('msmn-producer','community-media','msmn-training','Minjerribah Screen & Media Network'),
  ('msmn-research-writer','community-media','msmn-training','Minjerribah Screen & Media Network'),
  ('msmn-camera-sound','community-media','msmn-training','Minjerribah Screen & Media Network'),
  ('msmn-edit-caption','community-media','msmn-training','Minjerribah Screen & Media Network'),
  ('msmn-permissions','community-media','msmn-training','Minjerribah Screen & Media Network'),
  ('msmn-screen-crew','events','msmn-training','Minjerribah Screen & Media Network'),
