ON CONFLICT (id) DO NOTHING;

INSERT INTO learning_course_versions (course_id,revision,state,title,description,lessons_json,practical) VALUES
  ('msmn-site-tour',1,'draft','Explore Minjerribah Screen & Media Network',
   'Find the public project ideas, connected work, participation routes and sources.',
   json_array(
     json('{"title":"Tour the public pages","body":"Start with the opening page. Follow the network, places, funding and participation pages. Keep project ideas, illustrative budgets and actual invitations distinct in your notes.","captureNotes":"Capture the public site’s navigation and sources page using only material cleared for public viewing. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
     json('{"title":"Pick a route to explore","body":"Choose a story, screen, venue, crew or workshop idea. Use the sources and participation links to find the responsible contact. Check how a named project or organisation describes its own status."}')
   ),
   ''),
  ('msmn-story-contributor',1,'draft','MSMN Story contributor welcome',
   'Bring a local story idea and identify whose knowledge and permissions matter.',
   json_array(
     json('{"title":"Write a first story note","body":"Describe the story, possible audience and why it matters locally. Note who should be asked first and which sources can be verified. Where a story involves cultural knowledge, ask the appropriate custodians about authority and possible uses.","captureNotes":"Capture a made-up pitch card and the public Join the build page. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
     json('{"title":"Agree the boundaries before collecting","body":"Discuss what contributors are willing to share, with whom and in which channels. Record credits and any limits. Ask the responsible producer how to handle material if a person changes their mind."}')
   ),
   ''),
  ('msmn-trainee',1,'draft','MSMN Media trainee welcome',
   'Choose a practical starter task and agree supervision, equipment and feedback.',
   json_array(
     json('{"title":"Find a starter task","body":"Select something small enough to practise during a workshop, such as logging a take, checking a caption or writing a shot description. Confirm who will demonstrate it and provide feedback.","captureNotes":"Show a fictional workshop list and chosen task card. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
     json('{"title":"Finish with a useful handover","body":"Return equipment and describe what you produced, where it is kept and whether it cleared review. Ask what you should practise next. Agree separately whether you can use any work in a portfolio."}')
   ),
   ''),
  ('msmn-producer',1,'draft','MSMN Producer and project coordinator handover',
   'Move a proposal from idea to an agreed plan for people, place, equipment and approvals.',
   json_array(
     json('{"title":"Set a workable scope","body":"Write what the project will deliver, the audience and what can fit the available team and resources. Assign someone to confirm the venue, permissions, funding status and each public claim.","captureNotes":"Record a fictional project card beside the public network or funding page. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A venue conversation is positive and the project has a filmmaker. What does a scoped brief still need?","choices":[{"id":"a","text":"The confirmed venue status, permissions owner, crew capacity and costs to check."},{"id":"b","text":"Only a working title and an audience estimate."},{"id":"c","text":"A confirmed public date based on everyone being interested."}],"correct_choice_id":"a","explanation":"A workable production scope identifies its real dependencies.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An edit adds new audience uses that were never discussed. What should the producer do?","choices":[{"id":"a","text":"Treat the approval of the original brief as covering the new uses."},{"id":"b","text":"Ask who can approve the additional uses and record the result before release."},{"id":"c","text":"Send the new version to another channel without updating the permission notes."}],"correct_choice_id":"b","explanation":"New uses may require a new decision from the relevant people.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
     json('{"title":"Hand over the production record","body":"Give the next lead the approved brief, current run sheet, status of permissions, cost assumptions, next decisions and ready contacts. Label prospective partners by their actual level of involvement.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An incoming coordinator sees three versions of the run sheet. What should your handover identify?","choices":[{"id":"a","text":"The newest filename without checking its status."},{"id":"b","text":"The original run sheet only because it was approved once."},{"id":"c","text":"The approved current version and open decisions, with the relevant owners."}],"correct_choice_id":"c","explanation":"The coordinator needs the version that actually governs current work.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An organisation says it is interested. How should it appear in the plan?","choices":[{"id":"a","text":"As interested until a more specific commitment is agreed"},{"id":"b","text":"As confirmed delivery partner"}],"correct_choice_id":"a","explanation":"The team needs accurate commitments to plan with.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
   ),
   'Make a fictional one-page production handover for a local short film. Include a named decision owner, two dependencies and an agreed next checkpoint.'),
  ('msmn-research-writer',1,'draft','MSMN Researcher and writer handover',
   'Turn an idea into a short verified story brief with permission to use the material.',
   json_array(
     json('{"title":"Start with the claim and source","body":"List the main facts the story needs, their sources and the people who can verify disputed or unclear details. Label reconstructions and creative elements in your working brief.","captureNotes":"Show a fictional story treatments folder with source and open-question columns. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two sources disagree on a date. What belongs in the brief?","choices":[{"id":"a","text":"The date from the newest document with no mention of the older one."},{"id":"b","text":"The two sources, marked discrepancy and intended authoritative check."},{"id":"c","text":"An average or approximate date that avoids the disagreement."}],"correct_choice_id":"b","explanation":"Open discrepancies need a way to be resolved before a factual claim is used.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A scene recreates something for which no footage exists. How should the draft describe it?","choices":[{"id":"a","text":"Treat it as documentary footage once cut with real interviews."},{"id":"b","text":"Avoid describing the source so viewers can form their own interpretation."},{"id":"c","text":"Clearly label the scene as a reconstruction or creative element."}],"correct_choice_id":"c","explanation":"The review brief needs to show what the production is reconstructing.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
     json('{"title":"Prepare the interview and review","body":"Draft questions, check proposed naming and public uses, agree the review step with the producer and pass on the fact-check list. Keep things the source restricted outside the shared edit.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A new interview adds a restricted detail. What should the editor receive?","choices":[{"id":"a","text":"The agreed usable material and a clear instruction about the excluded detail."},{"id":"b","text":"A full transcript and a request to decide which details might be sensitive."},{"id":"c","text":"Only the redacted file, with no indication a restriction needs to carry forward."}],"correct_choice_id":"a","explanation":"The editor needs the relevant limit and usable source material.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"How should a draft label an unverified claim?","choices":[{"id":"a","text":"Write it as a confirmed fact until challenged"},{"id":"b","text":"Flag it for checking with the appropriate source"}],"correct_choice_id":"b","explanation":"The editor must see where evidence is still needed.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
   ),
   'Create a six-line fictional story brief with one verified fact, one research question, an interview contact role and a use restriction.'),
  ('msmn-camera-sound',1,'draft','MSMN Camera and sound crew',
   'Make a simple, usable recording and hand its files to the editor.',
   json_array(
     json('{"title":"Check the shoot before rolling","body":"Read the brief and permitted shots, locations and people. Check framing, sound and recording levels with a short test. Agree a way to signal a problem and confirm which filename or slate identifies the take.","captureNotes":"Capture a tabletop demonstration with no private subject or recognisable record. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A test recording has a clean image and distorted voice audio. What do you do first?","choices":[{"id":"a","text":"Record the scene and leave distortion for the editor to repair."},{"id":"b","text":"Use the clean image as evidence that the sound file will be usable."},{"id":"c","text":"Adjust the audio setup and test again before recording the take."}],"correct_choice_id":"c","explanation":"A short test should make both image and audio issues visible.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two takes are called by the same name. What should the shot log do?","choices":[{"id":"a","text":"Give them distinct identifiers and note the relevant sound and image differences."},{"id":"b","text":"Rename only the preferred take and discard the other identifier."},{"id":"c","text":"Leave both with the same name and ask the editor to check timestamps."}],"correct_choice_id":"a","explanation":"Distinct identifiers let the crew and editor discuss the same take.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
     json('{"title":"Log and transfer the takes","body":"Record the useful take names, sound problems and permission restrictions. Make the agreed backup and transfer to the authorised editor. Keep originals and the handover log together.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A backup is made but the transfer lacks take notes. What should be delivered?","choices":[{"id":"a","text":"Only the highest resolution copies to avoid confusion."},{"id":"b","text":"The approved files and a matching log of sound issues, restrictions and backups."},{"id":"c","text":"All files without information so the editor can choose freely."}],"correct_choice_id":"b","explanation":"The log helps the editor use the right source under the right conditions.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"You notice a good take includes a person whose permission is unclear. What goes in the handover?","choices":[{"id":"a","text":"Flag the take and hold that use for review"},{"id":"b","text":"Leave the detail out so the editor can decide from the picture"}],"correct_choice_id":"a","explanation":"The editor needs the restriction alongside the media.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
   ),
   'Produce a fictional three-shot plan and write a two-take handover with one missing permission and a suggested reshoot.'),
  ('msmn-edit-caption',1,'draft','MSMN Editing and captions',
   'Make a short edit that carries its source, captions and approvals through to delivery.',
   json_array(
     json('{"title":"Assemble a review cut","body":"Start from the agreed brief and authorised files. Keep the originals, identify the revision and mark rough or restricted material for review. Verify that names and dates match the checked sources.","captureNotes":"Capture a fictional timeline and the exported review cut filename. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A cut contains an unverified date and a restricted shot. What do you send for review?","choices":[{"id":"a","text":"A labelled work-in-progress with the fact and permission issues clearly flagged."},{"id":"b","text":"The cut as the final export and a verbal note to check it later."},{"id":"c","text":"A file that removes the flags because no one outside the crew can see it yet."}],"correct_choice_id":"a","explanation":"The reviewer needs to know which details still need a decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A name is audible in the edit but captions are misspelled. What do you do?","choices":[{"id":"a","text":"Match only the spelling guessed by speech recognition."},{"id":"b","text":"Check the name against a reliable source and correct the caption timing and text."},{"id":"c","text":"Delete the name from the captions and leave the rest unchecked."}],"correct_choice_id":"b","explanation":"Captions should accurately communicate the recording and verified wording.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
     json('{"title":"Check captions and exports","body":"Check that captions match the spoken words, timing and relevant sounds. Review the output in its intended landscape or portrait layout. Pass the approved source, credits and release conditions to whoever publishes it.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The approved landscape cut is adapted to portrait. What should be checked?","choices":[{"id":"a","text":"Only that the video is the correct aspect ratio."},{"id":"b","text":"Only that the same audio file has been copied."},{"id":"c","text":"Framing, readable captions, credits and whether the new use is approved."}],"correct_choice_id":"c","explanation":"A format change can affect both readability and the authorised use.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which version should move to the publishing step?","choices":[{"id":"a","text":"The newest file automatically"},{"id":"b","text":"The identified reviewed cut with checked captions, credits and permissions"}],"correct_choice_id":"b","explanation":"A later export might still be a working draft.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
   ),
   'Draft an edit checklist for a fictional 45-second clip. Include a caption correction, a permission check and two output contexts.'),
  ('msmn-permissions',1,'draft','MSMN Permissions and cultural review coordination',
   'Plan the permissions and evidence trail for a story, recorded activity or screening.',
   json_array(
     json('{"title":"Identify the person who can decide","body":"List the material, its source, intended audiences, and who holds relevant permission. Approach the appropriate cultural custodians about cultural material. Ask for the method and scope of review they want.","captureNotes":"Use a fictional permission register without real identities, private files or sensitive knowledge. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Which combination belongs in a useful permission request?","choices":[{"id":"a","text":"Item and a request to authorise every future use by default."},{"id":"b","text":"Item, authority, audience, specific uses and how the person wants to review them."},{"id":"c","text":"Item, a publishing date and the producer''s preferred platform only."}],"correct_choice_id":"b","explanation":"Clear scope lets the right person make an informed decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two people offer conflicting instructions about cultural material. What should the team do?","choices":[{"id":"a","text":"Choose the most convenient instruction in order to finish the edit."},{"id":"b","text":"Record both as permissions and release a shorter version."},{"id":"c","text":"Hold the proposed use and seek direction from the appropriate authorised custodian."}],"correct_choice_id":"c","explanation":"Cultural authority needs to be clear before using the material.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
     json('{"title":"Hand over the limits with the assets","body":"Record what use was agreed, who made the decision, any expiry or review date and what the team must withhold. Give the crew and editor the relevant instruction before capture or release.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Permission covers a community screening and expires before online release. What goes into the handover?","choices":[{"id":"a","text":"The permitted event, time limit and separate decision needed for online release."},{"id":"b","text":"A general approved label since the material was screened once."},{"id":"c","text":"An online export marked suitable if the same footage is used."}],"correct_choice_id":"a","explanation":"Permission changes according to the scope and timing agreed.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Does the producer’s approval cover cultural material by itself?","choices":[{"id":"a","text":"Check for the appropriate custodian’s approval and its scope"},{"id":"b","text":"Treat the production plan as cultural permission"}],"correct_choice_id":"a","explanation":"The appropriate custodian decides the use of cultural material.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
   ),
   'Write a fictional permissions table with one cleared use, one limited use and one item still awaiting a decision. Record how the editor will know which is which.'),
  ('msmn-screen-crew',1,'draft','MSMN Screening and event crew',
   'Set up an agreed screening, welcome the audience and hand back equipment.',
   json_array(
     json('{"title":"Prepare the run sheet","body":"Confirm the screening and venue decisions with the lead. Allocate projection, sound, audience welcome, accessible seating and pack-down. Ask who can pause or change the programme.","captureNotes":"Record a practice set-up and a fictional crew run sheet. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The run sheet lists audience welcome and AV test at the same time. What should be reviewed?","choices":[{"id":"a","text":"Whether an audience member could cover welcome if people arrive early."},{"id":"b","text":"Whether the AV test can be dropped to simplify the schedule."},{"id":"c","text":"Named crew for each duty, a backup and the timing of their checks."}],"correct_choice_id":"c","explanation":"Critical jobs need enough crew and time to be carried out.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"The intended screening file has captions, but no one has checked them on the actual screen. What do you do?","choices":[{"id":"a","text":"Test the file and caption readability with the intended equipment before opening."},{"id":"b","text":"Test only whether the file launches on a laptop."},{"id":"c","text":"Leave caption checking until a viewer asks about it."}],"correct_choice_id":"a","explanation":"A playback check on the equipment verifies the actual experience.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
     json('{"title":"Rehearse failures and close the session","body":"Test the agreed file and captions, then practise what the lead will do if equipment or conditions change. At the end, return gear, report faults and record the handover.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A cable fault is discovered during pack-down. What is a useful handover?","choices":[{"id":"a","text":"Return it to the same storage with no tag until the next screen test."},{"id":"b","text":"Identify the item, what happened and who will check or replace it."},{"id":"c","text":"Record only that equipment was returned on time."}],"correct_choice_id":"b","explanation":"A specific fault record helps the next crew avoid an unplanned failure.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Who confirms a public change to the screening plan?","choices":[{"id":"a","text":"Each crew member posting their own version"},{"id":"b","text":"The responsible event lead through the agreed channel"}],"correct_choice_id":"b","explanation":"One confirmed message helps the audience and crew follow the same plan.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
   ),
   'Write a fictional screening crew card with a sound or subtitle test, setup owner, change contact and gear check at handover.'),
  ('msmn-host',1,'draft','MSMN Venue host and local partner welcome',
   'Work through a proposed screening or workshop before confirming a venue or support.',
   json_array(
     json('{"title":"Work out what you can offer","body":"Describe possible space, availability, people, equipment or support. Ask what the organiser can supply, who will supervise, and what publicity or attribution would be appropriate.","captureNotes":"Use a fictional venue discussion, with the public hosting or participation route on screen. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
     json('{"title":"Check the agreement and follow-up","body":"Discuss access, responsibilities, restrictions, dates, costs and the decision still needed. Agree how the proposed collaboration may be described while the discussion is underway."}')
   ),
   '')
ON CONFLICT (course_id,revision) DO NOTHING;

-- Ready SETCO Skills & Work
INSERT INTO learning_courses (id,category_id,site_id,provider_name) VALUES
  ('training-site-tour','site-tours','ready-setco-training','Ready SETCO Skills & Work'),
  ('training-local-work','working-holiday','ready-setco-training','Ready SETCO Skills & Work'),
  ('training-working-holiday','working-holiday','ready-setco-training','Ready SETCO Skills & Work'),
  ('training-employer-founding','employers','ready-setco-training','Ready SETCO Skills & Work'),
  ('training-employer-onboarding','employers','ready-setco-training','Ready SETCO Skills & Work'),
  ('training-grant-writing','grants','ready-setco-training','Ready SETCO Skills & Work'),
  ('training-grant-delivery','grants','ready-setco-training','Ready SETCO Skills & Work'),
  ('training-volunteer','volunteers','ready-setco-training','Ready SETCO Skills & Work'),
  ('training-crew','events','ready-setco-training','Ready SETCO Skills & Work'),
  ('training-digital-stewardship','digital-stewardship','ready-setco-training','Ready SETCO Skills & Work'),
  ('training-ai-work-skills','digital-skills','ready-setco-training','Ready SETCO Skills & Work'),
  ('training-committee-basics','committee','ready-setco-training','Ready SETCO Skills & Work')
ON CONFLICT (id) DO NOTHING;

INSERT INTO learning_course_versions (course_id,revision,state,title,description,lessons_json,practical) VALUES
  ('training-site-tour',1,'draft','Find your way around Ready SETCO',
   'Explore the public lessons, local project pages, private portal and ways to take part.',
   json_array(
     json('{"title":"Start with a public page","body":"From the homepage, open Take part and try the sample volunteer lesson. Explore Training & work, the community map and the proposed cooperative formation pages for routes that suit you.","captureNotes":"Capture the public home and sample lesson. Use the public pages in the recording. Reference site: https://ready-setco.auraofintelligence.workers.dev/"}'),
     json('{"title":"Choose the next step","body":"Send an enquiry if you want a private follow-up. Use your own portal account when you need to access a group, see assigned courses or keep a private participation record. Ask the organiser which process applies to your goal."}')
   ),
   ''),
  ('training-local-work',1,'draft','Get ready for local paid work',
   'Prepare a short work profile and ask useful questions before taking on a local job.',
   json_array(
     json('{"title":"Describe what you can do","body":"List relevant tasks, experience and availability. Pick one example that shows your skill. Keep identity documents and contact details out of public posts. Offer any evidence through the agreed private review process.","captureNotes":"Use a fictional Learning & work profile in an authorised test account. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Which work profile statement gives an employer something useful to discuss?","choices":[{"id":"a","text":"A broad claim to be available for any role, without an example."},{"id":"b","text":"A specific skill example, actual availability and a question about the role."},{"id":"c","text":"A list of identity document numbers to prove readiness publicly."}],"correct_choice_id":"b","explanation":"Relevant examples and availability help a conversation without exposing private evidence.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A role asks for a licence check. What should you share first in the public enquiry?","choices":[{"id":"a","text":"A full scan and its number so the employer can check it later."},{"id":"b","text":"The same document to every business linked to the project."},{"id":"c","text":"The relevant licence type and ask how the authorised check is handled."}],"correct_choice_id":"c","explanation":"Verification can be arranged privately and scoped to the actual role.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Clarify a role before saying yes","body":"Ask who the employer is, what work is required, where and when it happens, who supervises and what training or checks apply. Ask how pay and work arrangements will be confirmed.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two organisations are named on a job idea, and neither is identified as the employer. What do you ask?","choices":[{"id":"a","text":"Who actually employs and supervises, what terms apply and how they are agreed."},{"id":"b","text":"Which one designed the form because that company must be the employer."},{"id":"c","text":"Which one is the largest and whether it can send a general pay schedule."}],"correct_choice_id":"a","explanation":"The actual employer and supervisor need to be clear.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which detail should be clear before agreeing to a role?","choices":[{"id":"a","text":"The actual employer, duties, arrangements and supervisor"},{"id":"b","text":"Only the name of a project"}],"correct_choice_id":"a","explanation":"The actual role determines what you and the employer need to agree.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
   ),
   'Write a fictional profile and a short message to an employer asking about duties, hours, training and the next step.'),
  ('training-working-holiday',1,'draft','Prepare for working holiday work',
   'Find the official sources, keep useful work records and ask what a role involves.',
   json_array(
     json('{"title":"Check the current rules for your situation","body":"Use the relevant Home Affairs pages and the official work-rights process where applicable. Match the actual job, location and dates to the current guidance for your situation. Keep the source and date of your check.","captureNotes":"Show the site’s working-holiday pathway and where to find current official pages. Use fictional records and avoid displaying personal documents. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An old example and a current official page give different conditions. Which do you use?","choices":[{"id":"a","text":"Use the older example if it matches your plans more closely."},{"id":"b","text":"Apply the same rule to all workers on working holidays."},{"id":"c","text":"Use the current official guidance for your actual visa and job, and date the check."}],"correct_choice_id":"c","explanation":"Conditions depend on current guidance and the person''s actual situation.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A town is listed on a promotional page but the employer proposes shifts elsewhere. What should be checked?","choices":[{"id":"a","text":"The actual work location and duties against the relevant current guidance."},{"id":"b","text":"The business''s registered address only."},{"id":"c","text":"The promotional listing as proof for every shift."}],"correct_choice_id":"a","explanation":"It is the actual work and location that need checking.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Prepare records and ask before you start","body":"Ask the employer about the actual tasks, location, pay and records they provide. Agree how to keep payslips, contracts and work dates. Treat community volunteering as a separate activity and check any claim about specified work with the official source.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An employer says records will be supplied later and asks you to start now. What should you clarify?","choices":[{"id":"a","text":"Only whether the employer has hired working holiday workers before."},{"id":"b","text":"The role and pay terms, and which dates and evidence they will record and provide."},{"id":"c","text":"Whether the volunteer team can write one confirmation for all kinds of work."}],"correct_choice_id":"b","explanation":"Work agreements and records need to match the actual arrangement.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A job listing claims it will count. What should you do?","choices":[{"id":"a","text":"Rely on the listing’s claim by itself"},{"id":"b","text":"Check the current official rules against the actual role and location"}],"correct_choice_id":"b","explanation":"The relevant official conditions and actual work matter.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
   ),
   'Prepare a fictional job enquiry with four questions, a place to record your official check and a list of employment evidence you would keep.'),
  ('training-employer-founding',1,'draft','Local employers helping found Ready SETCO',
   'Prepare a contribution to the cooperative’s first decisions and identify what needs an agreement.',
   json_array(
     json('{"title":"Bring one need and one offer","body":"Name a local employment, training or resource need. Describe what the business might contribute and what conditions it would need. Use the declared formation status when speaking to staff or other businesses.","captureNotes":"Capture the public participation and formation pages with a fictional local employer. Reference site: https://ready-setco.auraofintelligence.workers.dev/"}'),
     json('{"title":"Move from discussion to an accountable decision","body":"Separate a founding idea from an approved contribution or recruitment arrangement. Identify who can authorise each commitment and who keeps the record. Discuss which responsibilities the business would retain."}')
   ),
   ''),
  ('training-employer-onboarding',1,'draft','Local employers exploring participation after formation',
   'Prepare the questions and evidence for a future employer membership or service enquiry.',
   json_array(
     json('{"title":"Compare the type of participation","body":"Ask whether you are exploring membership, sharing a resource, offering jobs or buying a service. Check the status and applicable terms when that route exists. Identify who can speak for the business.","captureNotes":"Use the public membership page and an example employer enquiry. Reference site: https://ready-setco.auraofintelligence.workers.dev/"}'),
     json('{"title":"Confirm what the business would actually do","body":"Document responsibilities, timing, costs, information handling and who makes hiring and supervision decisions. If arranging introductions, confirm the role and what the person has agreed may be shared through the authorised process."}')
   ),
   ''),
  ('training-grant-writing',1,'draft','Write a community grant proposal',
   'Turn a local idea into a clear need, workable budget and evidence checklist.',
   json_array(
     json('{"title":"Read the current programme guide","body":"Confirm the applicant, intent, eligibility, deadline and evidence with the official round material. Describe who benefits and what local evidence supports the need. Record what you still need to verify.","captureNotes":"Show the Ready SETCO Grants page and a fictional grant outline. Confirm any external round details at recording time. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two grant rounds have similar names. What do you verify first?","choices":[{"id":"a","text":"Find the round with the biggest budget and reuse last year''s eligibility notes."},{"id":"b","text":"Use a current announcement to assume the detailed conditions are identical."},{"id":"c","text":"The official guide for the actual round covering applicant, activity, dates and evidence."}],"correct_choice_id":"c","explanation":"The actual round document gives the terms a proposal needs to meet.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"The draft says many residents need a service but gives no evidence. What should you add?","choices":[{"id":"a","text":"A relevant local source or participation evidence showing who needs it and why."},{"id":"b","text":"A broader regional estimate without explaining its relation to the area."},{"id":"c","text":"An extra paragraph repeating the same claim in stronger words."}],"correct_choice_id":"a","explanation":"A reviewer needs to connect the claimed need to evidence.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Write the plan that could be delivered","body":"Connect activities, dates, costs and outcomes. Separate confirmed contributions from proposals and attach evidence of quotes or approval where the programme needs it. Have someone review the draft against the criteria.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"One activity cost is estimated and another is quoted. What goes in the budget?","choices":[{"id":"a","text":"Both as confirmed costs because a total is already needed."},{"id":"b","text":"Both as separate lines with their evidence status and a check for the estimate."},{"id":"c","text":"Only the quoted line and an unexplained buffer in the total."}],"correct_choice_id":"b","explanation":"Clear status makes the budget reviewable and the uncertainty visible.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An unconfirmed sponsorship is included in the budget. How should it appear?","choices":[{"id":"a","text":"As proposed with an owner to confirm it"},{"id":"b","text":"As committed income"}],"correct_choice_id":"a","explanation":"Budget reviewers need the funding status to judge whether the plan is viable.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
   ),
   'Draft a fictional grant summary, three budget lines, one eligibility check, an outcome and a source of evidence.'),
  ('training-grant-delivery',1,'draft','Deliver and report on a funded project',
   'Track commitments, approvals, receipts and outcomes from the first day of a fictional project.',
   json_array(
     json('{"title":"Set up the delivery checklist","body":"Read the agreed funding conditions. Record milestones, eligible spending instructions, receipts, who can approve changes and how to ask for a variation. Start the evidence folder before spending.","captureNotes":"Capture a fictional budget and milestone register with no real invoices or banking details. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A supplier price moves above a budget line before purchase. What do you check?","choices":[{"id":"a","text":"The relevant funding condition, authorised response and variation process if required."},{"id":"b","text":"Add it to a different line because the total grant is unchanged."},{"id":"c","text":"Wait to compare it during final reporting after paying."}],"correct_choice_id":"a","explanation":"Spending and changes need to be approved under the actual terms.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A volunteer report is proposed as outcome evidence. What makes it useful?","choices":[{"id":"a","text":"It is long and contains everyone''s private contact details."},{"id":"b","text":"It describes the relevant output, date and evidence handling agreed for the report."},{"id":"c","text":"It repeats the grant request so the reviewer can recognise the project."}],"correct_choice_id":"b","explanation":"The report needs relevant evidence that can be shared appropriately.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Prepare the close-out","body":"Compare approved and actual costs, report what changed and collect acceptable evidence of the outcome. Keep the reporting deadline, approval steps and outstanding issues visible to the next officer.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An approved variation moved a milestone. What do you report?","choices":[{"id":"a","text":"Only the new date with no reference to the agreement."},{"id":"b","text":"Only the original date and omit the reasons for differences."},{"id":"c","text":"The original and revised milestone, evidence of approval and what was actually delivered."}],"correct_choice_id":"c","explanation":"A complete evidence trail explains the change and its result.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A major cost changes during delivery. What should you check first?","choices":[{"id":"a","text":"Only the total funds remaining"},{"id":"b","text":"The funding agreement and the authorised change process"}],"correct_choice_id":"b","explanation":"A change can affect which costs or activities are authorised.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
   ),
   'Prepare a fictional close-out with budget versus actuals, one approved change, two outcomes and where their evidence is kept.'),
  ('training-volunteer',1,'draft','Your first community volunteer shift',
   'Choose a task, meet the shift lead and leave the next person a useful handover.',
   json_array(
     json('{"title":"Confirm the shift","body":"Ask where and when to check in, what work has been agreed, what training or gear you need and who makes a change-of-plan decision. Raise access needs with the lead.","captureNotes":"Use a fictional event run sheet and show a sample shift briefing. Reference site: https://ready-setco.auraofintelligence.workers.dev/"}'),
     json('{"title":"Close out your work","body":"Return the agreed equipment, tell the lead what was done and hand over unfinished actions. Ask how concerns and incidents are recorded. If the project is trialling voluntary contribution records, agree who could verify the time."}')
   ),
   ''),
  ('training-crew',1,'draft','Plan a community event and crew handover',
   'Build a short run sheet and rehearse a change to a local event.',
   json_array(
     json('{"title":"Give each job an owner","body":"Confirm the venue, expected audience, lead roles and time checks. Include accessible arrival, a contact for concerns, permission checks and the decision point for changing the schedule.","captureNotes":"Record a fictional event run sheet and point out the owner, due time and backup in each row. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An event has one person allocated to two jobs at doors open. How do you fix the run sheet?","choices":[{"id":"a","text":"Shorten both job labels so the person can complete them faster."},{"id":"b","text":"Wait until doors open to ask whoever is free to handle one."},{"id":"c","text":"Give each simultaneous job time, an owner and a backup as needed."}],"correct_choice_id":"c","explanation":"A live plan has to account for roles needing attention at the same time.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two arrival paths are shown and one may be inaccessible. What do you include?","choices":[{"id":"a","text":"The confirmed accessible route and the person checking any uncertainty."},{"id":"b","text":"The shortest path only because it is simpler to publicise."},{"id":"c","text":"Both directions without specifying which needs checking."}],"correct_choice_id":"a","explanation":"The audience needs workable arrival details and a contact.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Rehearse the handover","body":"Practise a late venue change with the crew. Ask the authorised person to confirm the public wording and updated channels. At close, check the equipment and record any issue for the next team.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A text message circulates a different venue after a change. What should the lead do?","choices":[{"id":"a","text":"Send another version privately without updating the public notice."},{"id":"b","text":"Confirm the current source and share one agreed update through the chosen channels."},{"id":"c","text":"Wait until people arrive to explain the two options."}],"correct_choice_id":"b","explanation":"A coordinated message sets out the verified change and where it applies.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What should a crew handover contain after a change?","choices":[{"id":"a","text":"Just the name of the event"},{"id":"b","text":"The agreed update, source, people responsible and what still needs doing"}],"correct_choice_id":"b","explanation":"The next team needs instructions and open actions they can verify.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
   ),
   'Write a fictional run sheet with a venue contact, three crew jobs, one change decision and a closing check.'),
  ('training-digital-stewardship',1,'draft','Record a place with permission',
   'Practise care with map entries, local research sources and decisions about what may be shared.',
   json_array(
     json('{"title":"Record a useful observation","body":"Choose a fictional public place. Record what you saw, when, how to check it and what people need to know. Explain where a map pin or photograph came from and the audience it suits.","captureNotes":"Use a fictional map entry and the Ready SETCO public map or Cultural Intelligence Node reference material. Do not submit a live example. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A map pin came from a contributed photo without an exact location. How should it be recorded?","choices":[{"id":"a","text":"Record the source and uncertainty and check the place before publishing a precise pin."},{"id":"b","text":"Infer the position from a similar-looking place and mark it confirmed."},{"id":"c","text":"Choose a central location because the photo is genuine."}],"correct_choice_id":"a","explanation":"A genuine observation does not automatically establish a precise point.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two neighbours report different opening times for a public place. What do you do?","choices":[{"id":"a","text":"Replace both with the longer hours to make the map more useful."},{"id":"b","text":"Keep their observations distinct and check the current source before updating."},{"id":"c","text":"Treat the later report as definitive without noting its source."}],"correct_choice_id":"b","explanation":"Corrections should retain provenance and a reason for the public update.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Keep ownership and limits with the record","body":"Before sharing locations, personal details or cultural knowledge, ask who has authority and which audience and uses they approve. Preserve corrections and contact the custodian if the approved scope changes.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A custodian clears an observation for a small workshop but it appears in a draft map. What is appropriate?","choices":[{"id":"a","text":"Remove the name and publish because the record is useful."},{"id":"b","text":"Publish it briefly while checking whether anyone objects."},{"id":"c","text":"Keep it within its approved workshop use and ask about the proposed public use."}],"correct_choice_id":"c","explanation":"Changing the audience needs a separate scope decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A source supplies a location with restricted access. What should you do?","choices":[{"id":"a","text":"Record the restriction and confirm any intended use with the authorised custodian"},{"id":"b","text":"Copy it into a public map so people can verify it"}],"correct_choice_id":"a","explanation":"Anyone handling the record needs the same use instructions.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
   ),
   'Draft a fictional observation with its source, check date, approved audience and one item that would stay in the private working record.'),
  ('training-ai-work-skills',1,'draft','Use AI to help with a practical task',
   'Draft a checklist with AI and check it against a reliable human or written source.',
   json_array(
     json('{"title":"Make the request specific","body":"Choose a low-risk task such as making a fictional event checklist clearer. Describe the audience, job and output. Use fictional details and leave out private names, sensitive instructions and records.","captureNotes":"Record an example in a chosen tool using made-up inputs. Show the prompt and draft as separate items. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Which prompt gives enough detail for a low-risk checklist draft?","choices":[{"id":"a","text":"Paste a real contact list and ask for a useful plan of any kind."},{"id":"b","text":"State the audience, task, fictional context, desired output and any limits."},{"id":"c","text":"Ask it to guess the latest venue procedures and skip reviewing the answer."}],"correct_choice_id":"b","explanation":"Specific fictional inputs help the model draft something the user can check.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An AI answer includes a private operational detail from your input. What should you do before sharing?","choices":[{"id":"a","text":"Share it internally first and ask if anyone recognises the detail."},{"id":"b","text":"Leave it in because the model returned it unchanged."},{"id":"c","text":"Remove it, adjust the inputs and use only details approved for the audience."}],"correct_choice_id":"c","explanation":"The author controls what information goes into the shared output.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Check every instruction before using it","body":"Compare the answer with the real, authorised process. Remove guesses, confirm names or facts with the source and ask the responsible person to review it. Keep the useful prompt and the corrected version together.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The model produces a clear checklist that disagrees with the official process. What should happen?","choices":[{"id":"a","text":"Follow the authorised source, correct the draft and ask the responsible person to review it."},{"id":"b","text":"Prefer the model wording because most learners find it clear."},{"id":"c","text":"Add both versions and let the learner decide what applies."}],"correct_choice_id":"a","explanation":"Clarity is valuable and the agreed operating process still governs.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An AI draft invents a venue rule. What should you do?","choices":[{"id":"a","text":"Keep it because it sounds plausible"},{"id":"b","text":"Check the actual venue source and correct or remove it"}],"correct_choice_id":"b","explanation":"The venue rules need a source that has authority.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
   ),
   'Write a short fictional prompt, show one improvement from the AI draft, identify a claim needing verification and give your checked final wording.'),
  ('training-committee-basics',1,'draft','Run a meeting and hand over decisions',
   'Practise preparing an agenda, recording a decision and giving the next officer a clear handover.',
   json_array(
     json('{"title":"Prepare the decision","body":"Set out the purpose, topic and decision required. Check who can take part in it, how interests should be handled and what evidence is available. Keep a versioned draft agenda.","captureNotes":"Show a made-up meeting using the public Ready SETCO formation planner. Reference site: https://ready-setco.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The committee needs to choose a supplier, but one member has a relevant interest. What should happen?","choices":[{"id":"a","text":"Proceed with the discussion and mention the interest only if the vote is close."},{"id":"b","text":"Assume an informal conversation is enough and omit it from the record."},{"id":"c","text":"Use the applicable disclosure and decision process before the choice and record the outcome."}],"correct_choice_id":"c","explanation":"The relevant process and record help everyone see how the decision was made.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"The agenda proposes a vote but the papers contain no cost evidence. What is useful preparation?","choices":[{"id":"a","text":"Flag the missing evidence, who will obtain it and whether a decision can go ahead."},{"id":"b","text":"Treat the costs from an unrelated project as an approved budget."},{"id":"c","text":"Let the meeting decide a spending limit without saying estimates are missing."}],"correct_choice_id":"a","explanation":"Chair and members need to know what evidence is available for a decision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}'),
     json('{"title":"Write what happens next","body":"Record the actual approved wording, date and action owner. Give the incoming officer the decision source, open issues, relevant authorised access and a check-in date.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An action was agreed but the incoming officer finds a later informal variation. What should they use?","choices":[{"id":"a","text":"Use the newer informal message as the only source."},{"id":"b","text":"Check the actual decision and which authorised record, if any, changed it."},{"id":"c","text":"Create another action without linking it to the earlier decision."}],"correct_choice_id":"b","explanation":"The handover should preserve the authority and history of both the decision and any revision.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What makes a decision record useful to someone taking over?","choices":[{"id":"a","text":"The actual decision, its source, an action owner and due date"},{"id":"b","text":"A generic note that the topic was discussed"}],"correct_choice_id":"a","explanation":"The next officer can verify the decision and continue the work.","source_refs":["https://ready-setco.auraofintelligence.workers.dev/"]}]}')
   ),
   'Prepare a fictional agenda, one decision and three handover actions. Mark one item that needs authority or a follow-up check.')
ON CONFLICT (course_id,revision) DO NOTHING;
